class EntityBase(BaseModel):
    """Common columns every table carries."""

    model_config = ConfigDict(extra="forbid", use_enum_values=False)
    __entity__: ClassVar[str] = ""
    __table__: ClassVar[str] = ""
    __checks__: ClassVar[tuple[tuple[str, str, str], ...]] = ()

    id: UUID = Field(default_factory=uuid4)
    ontology_version: str = ONTOLOGY_VERSION
    created_at: datetime | None = None
    created_by: str | None = None

    @model_validator(mode="after")
    def _run_checks(self) -> EntityBase:
        if not self.__checks__:
            return self
        ns = {k: (v.value if hasattr(v, 'value') else v) for k, v in self.__dict__.items()}
        for check_id, expr, description in self.__checks__:
            if not evaluate(expr, ns):
                raise ValueError(f"{check_id}: {description}")
        return self

    def row(self) -> dict[str, Any]:
        """Column values for an insert, enums as their codes, omitting unset common columns."""
        data = self.model_dump(mode="python")
        for k in ("created_at", "created_by"):
            if data.get(k) is None:
                data.pop(k, None)
        return {k: (v.value if hasattr(v, 'value') else v) for k, v in data.items()}


